#!/usr/bin/env python3
"""Script to generate tests/fixtures/field-adoption with invented content."""
import json
import os
import shutil
from pathlib import Path

FIXTURE_DIR = Path(__file__).resolve().parent / "field-adoption"


def generate_fixture():
    if FIXTURE_DIR.exists():
        shutil.rmtree(FIXTURE_DIR)
    FIXTURE_DIR.mkdir(parents=True, exist_ok=True)

    # 1. package.json
    (FIXTURE_DIR / "package.json").write_text(
        json.dumps({
            "name": "field-adoption-fixture",
            "version": "1.0.0",
            "scripts": {
                "test": "echo ok"
            }
        }, indent=2) + "\n",
        encoding="utf-8"
    )

    # 2. Source and doc files for glob matching
    (FIXTURE_DIR / "src" / "components").mkdir(parents=True, exist_ok=True)
    (FIXTURE_DIR / "src" / "components" / "Button.tsx").write_text(
        "export const Button = () => <button>Click</button>;\n",
        encoding="utf-8"
    )
    (FIXTURE_DIR / "src" / "tokens.css").write_text(
        ":root {\n  --color-brand-1: #000001;\n}\n",
        encoding="utf-8"
    )
    (FIXTURE_DIR / "docs").mkdir(parents=True, exist_ok=True)
    (FIXTURE_DIR / "docs" / "index.md").write_text(
        "# Project Docs\n\nDocumentation for field adoption fixture.\n",
        encoding="utf-8"
    )

    # 3. .agents structure
    agents_dir = FIXTURE_DIR / ".agents"
    agents_dir.mkdir(parents=True, exist_ok=True)

    # 3a. project-profile.yaml (has exactly 1 unmatched glob: src/legacy_nonexistent)
    (agents_dir / "project-profile.yaml").write_text(
        """schema_version: 1

project:
  name: field-adoption-app
  summary: Field adoption fixture project for Build Forge release verification.
  mode: existing

stack:
  language: typescript
  framework: react
  package_manager: npm

commands:
  check: npm test
  test: npm test

structure:
  layers:
    - path: src/components
      purpose: UI components layer
    - path: docs
      purpose: Project documentation
    - path: src/legacy_nonexistent
      purpose: Missing legacy layer
  tests: colocated

git:
  push: ask
  commit_format: "<type>(<scope>): <subject>"
  scopes:
    - name: skills
      purpose: Agent skill files
      paths:
        - .agents/skills/**
    - name: docs
      purpose: Documentation
      paths:
        - docs/**
    - name: ui
      purpose: UI components
      paths:
        - src/components/**

rules:
  - id: ui-no-inline-styles
    area: design
    text: Never use inline styles in UI components.
    enforced_by: manual

docs:
  skills_dir: .agents/skills
  agents_file: AGENTS.md
  repo_map: .agents/repo-map.md
""",
        encoding="utf-8"
    )

    # 3b. AGENTS.md (has Scope guide holding rows skills, docs, and ui)
    (FIXTURE_DIR / "AGENTS.md").write_text(
        """# Agent Guidelines

## Areas
| Area | Description | Skill |
|---|---|---|
| design | UI component guidelines | app-ui |
| tokens | Design tokens | app-tokens |

## Git Commit Scopes
| Scope | Purpose | Paths |
|---|---|---|
| skills | Agent skill files | .agents/skills/** |
| docs | Documentation | docs/** |
| ui | UI components | src/components/** |
""",
        encoding="utf-8"
    )

    # 3c. references.yaml (lists vendor-listed only)
    (agents_dir / "references.yaml").write_text(
        """schema_version: 1
vendor_in_git: false
references:
  - name: vendor-listed
    kind: skill
    category: other
    status: declared
    mode: advisory
    activation: pipeline-only
    used_by:
      - audit
    summary: Invented listed vendor reference
""",
        encoding="utf-8"
    )

    # 3d. build-forge.lock.json will be written after skills are generated


    # 4. Skills in .agents/skills
    skills_dir = agents_dir / "skills"
    skills_dir.mkdir(parents=True, exist_ok=True)

    # 4a. app-ui: Stamped convention skill with:
    # - hand edits outside blocks (a 60 line interface table)
    # - a custom block over the limit (170 lines > 160 lines limit)
    ui_skill_dir = skills_dir / "app-ui"
    ui_skill_dir.mkdir(parents=True, exist_ok=True)
    ui_lines = [
        "---",
        "name: app-ui",
        "description: UI component guidelines and interface contracts.",
        "---",
        "",
        "# App UI",
        "",
        "<!-- GENERATED BY BUILD FORGE: do not edit this block directly -->",
        "## UI Guidelines",
        "- Use design tokens for all component colors.",
        "<!-- END GENERATED -->",
        "",
        "<!-- BEGIN CUSTOM: oversized_contracts -->"
    ]
    for k in range(1, 166):
        ui_lines.append(f"Custom contract line {k} component events must define payload contracts.")
    ui_lines.append("<!-- END CUSTOM: oversized_contracts -->")
    ui_lines.extend([
        "",
        "## Component Interface Specifications",
        "| Component | Prop | Type | Default | Description |",
        "|---|---|---|---|---|"
    ])
    for k in range(1, 61):
        ui_lines.append(f"| Component{k} | prop{k} | string | 'default{k}' | Description for prop {k} |")
    ui_lines.append("")
    (ui_skill_dir / "SKILL.md").write_text("\n".join(ui_lines), encoding="utf-8")

    # 4b. app-tokens: Stamped convention skill with:
    # - hand edits outside blocks (a 200 line token table)
    tokens_skill_dir = skills_dir / "app-tokens"
    tokens_skill_dir.mkdir(parents=True, exist_ok=True)
    tok_lines = [
        "---",
        "name: app-tokens",
        "description: Color, typography, and spacing tokens.",
        "---",
        "",
        "# App Tokens",
        "",
        "<!-- GENERATED BY BUILD FORGE: do not edit this block directly -->",
        "## Token Guidelines",
        "- All color definitions must reference semantic tokens.",
        "<!-- END GENERATED -->",
        "",
        "## Token Catalog",
        "| Token | Value | Role | Evidence |",
        "|---|---|---|---|"
    ]
    for k in range(1, 201):
        tok_lines.append(f"| --color-brand-{k} | #{k:06x} | brand | src/tokens.css:1 |")
    tok_lines.append("")
    (tokens_skill_dir / "SKILL.md").write_text("\n".join(tok_lines), encoding="utf-8")

    # 4c. app-data: An unstamped same-name skill with tables (>20 lines)
    data_skill_dir = skills_dir / "app-data"
    data_skill_dir.mkdir(parents=True, exist_ok=True)
    data_lines = [
        "---",
        "name: app-data",
        "description: Database models and data schemas.",
        "---",
        "",
        "# App Data",
        "",
        "## Data Schema Definitions",
        "| Table | Column | Type | Nullable | Description |",
        "|---|---|---|---|---|"
    ]
    for k in range(1, 26):
        data_lines.append(f"| users | col_{k} | varchar | YES | User attribute {k} |")
    data_lines.append("")
    (data_skill_dir / "SKILL.md").write_text("\n".join(data_lines), encoding="utf-8")

    # 4d. vendor-listed: Folder of 22 markdown files listed in references.yaml
    vl_dir = skills_dir / "vendor-listed"
    vl_dir.mkdir(parents=True, exist_ok=True)
    for i in range(1, 23):
        v_lines = [f"# Vendor Doc {i}", ""]
        for j in range(1, 26):
            v_lines.append(f"- Listed vendor rule {i}.{j}: format specification requirement.")
        (vl_dir / f"doc_{i}.md").write_text("\n".join(v_lines) + "\n", encoding="utf-8")

    # 4e. vendor-unlisted: Folder of 22 markdown files not listed in references.yaml (trips volume guard)
    vu_dir = skills_dir / "vendor-unlisted"
    vu_dir.mkdir(parents=True, exist_ok=True)
    for i in range(1, 23):
        v_lines = [f"# Unlisted Vendor Doc {i}", ""]
        for j in range(1, 26):
            v_lines.append(f"- Unlisted vendor rule {i}.{j}: unclassified third party statement.")
        (vu_dir / f"doc_{i}.md").write_text("\n".join(v_lines) + "\n", encoding="utf-8")

    # 4f. Core package skill for lock file tracking
    core_src = Path(__file__).resolve().parents[2] / "skills" / "project-blueprints"
    if core_src.is_dir():
        shutil.copytree(core_src, skills_dir / "project-blueprints", ignore=shutil.ignore_patterns("__pycache__", "*.pyc"), dirs_exist_ok=True)

    # 5. Write build-forge.lock.json with real hashes for package skills
    import hashlib
    lock_manifest = {"_version": "0.1.0"}
    pb_dir = skills_dir / "project-blueprints"
    if pb_dir.is_dir():
        for sf in sorted(pb_dir.rglob("*")):
            if sf.is_file():
                rel = sf.relative_to(skills_dir).as_posix()
                content = sf.read_text(encoding="utf-8").replace("\r\n", "\n")
                lock_manifest[f"skills/{rel}"] = hashlib.sha256(content.encode("utf-8")).hexdigest()

    (agents_dir / "build-forge.lock.json").write_text(
        json.dumps(lock_manifest, indent=2) + "\n",
        encoding="utf-8"
    )

    print(f"Generated fixture in {FIXTURE_DIR}")


if __name__ == "__main__":
    generate_fixture()
